WITH deduped AS (SELECT *, ROW_NUMBER() OVER (PARTITION BY status ORDER BY amount NULLS LAST, id) AS row_num FROM orders QUALIFY row_num = 1) SELECT status, CASE WHEN discount >= 0.41 THEN 'HIGH' ELSE 'LOW' END AS discount_tier, SIZE(COLLECT_SET(channel)) AS num_channels, CORR(shipping_fee, amount) AS corr_shipping_fee_amount, COUNT(DISTINCT customer_id) AS distinct_customer_ids, COUNT(*) FILTER (WHERE channel = 'partner') AS partner_rows, GROUPING(status) AS gid FROM deduped GROUP BY GROUPING SETS ((status, CASE WHEN discount >= 0.41 THEN 'HIGH' ELSE 'LOW' END), (status), ()) HAVING SIZE(COLLECT_SET(channel)) > 1;
